using System;
using System.IO;
using System.Linq;
using System.Threading;
using System.Diagnostics;
using System.Collections.Generic;
using System.Web.Script.Serialization;
namespace DomainConsole.Agent {
 internal static class CacheCleanup31 {
  static string Normal(string p){var full=Path.GetFullPath(p.StartsWith(@"\\?\",StringComparison.Ordinal)?p.Substring(4):p);return full==Path.GetPathRoot(full)?full:full.TrimEnd('\\');}
  static string Long(string p)=>@"\\?\"+Normal(p);
  static string fixtureRoot;
  static string[] Originals(){var win=fixtureRoot??Environment.GetFolderPath(Environment.SpecialFolder.Windows);return new[]{Path.Combine(win,"SoftwareDistribution"),Path.Combine(win,"SoftwareDistribution","Download"),Path.Combine(win,"SoftwareDistribution","EventCache"),Path.Combine(win,"SoftwareDistribution","EventCache.v2"),Path.Combine(win,"System32","catroot2")};}
  static bool Allowed(string path){var full=Normal(path);return Originals().Any(p=>full.StartsWith(p+".DomainConsolePendingDelete_",StringComparison.OrdinalIgnoreCase)&&Path.GetDirectoryName(full).Equals(Path.GetDirectoryName(p),StringComparison.OrdinalIgnoreCase));}
  static FileAttributes? Attrs(string path){try{return File.GetAttributes(Long(path));}catch(FileNotFoundException){return null;}catch(DirectoryNotFoundException){return null;}}
  static bool Exists(string p){var attrs=Attrs(p);if(attrs==null)return false;if((attrs.Value&FileAttributes.Directory)==0)throw new IOException("Ожидался каталог старого кэша");return true;}
  static void NoLinks(string path){var stack=new Stack<string>();stack.Push(path);while(stack.Count>0){var current=stack.Pop();var attrs=Attrs(current);if(attrs==null)continue;if((attrs.Value&FileAttributes.ReparsePoint)!=0)throw new IOException("Ссылка в старом кэше: "+current);if((attrs.Value&FileAttributes.Directory)==0)continue;try{foreach(var child in Directory.EnumerateFileSystemEntries(Long(current)))stack.Push(Normal(child));}catch(DirectoryNotFoundException){if(Exists(current))throw;}}}
  public static int Delete(string path){try{if(!Allowed(path))throw new IOException("Недопустимый путь отложенной очистки");if(!Exists(path))return 0;for(var parent=Path.GetDirectoryName(Normal(path));!string.IsNullOrEmpty(parent);parent=Path.GetDirectoryName(parent)){var a=Attrs(parent);if(a==null)throw new DirectoryNotFoundException(parent);if((a.Value&FileAttributes.ReparsePoint)!=0)throw new IOException("Ссылка в родительском пути; удаление не выполнено");}for(int attempt=0;attempt<3;attempt++){NoLinks(path);try{if(Exists(path))Directory.Delete(Long(path),true);return Exists(path)?1:0;}catch(DirectoryNotFoundException){if(!Exists(path))return 0;if(attempt==2)throw;Thread.Sleep(100);}}return 1;}catch(Exception ex){Console.Error.WriteLine(ex);try{File.WriteAllText(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData),"DomainConsoleCSharp","cache-delete-error.log"),DateTime.UtcNow.ToString("o")+Environment.NewLine+ex);}catch{}return 1;}}
  static List<string> Discover(){var result=new List<string>();foreach(var p in Originals()){var parent=Path.GetDirectoryName(p);if(!Exists(parent))continue;var a=Attrs(parent);if((a.Value&FileAttributes.ReparsePoint)!=0)continue;foreach(var path in Directory.EnumerateDirectories(Long(parent),Path.GetFileName(p)+".DomainConsolePendingDelete_*")){var n=Normal(path);if(Allowed(n))result.Add(n);}}return result.Distinct(StringComparer.OrdinalIgnoreCase).ToList();}
  public static int Smoke34(string root){Directory.CreateDirectory(root);fixtureRoot=Path.GetFullPath(root);var old=Path.Combine(root,"SoftwareDistribution.DomainConsolePendingDelete_fixture");var deep=old;while(deep.Length<360)deep=Path.Combine(deep,"segment-012345678901234567890123456789");Directory.CreateDirectory(Long(deep));File.WriteAllText(Long(Path.Combine(deep,"payload.bin")),"DELETE");var backup=Path.Combine(root,"SoftwareDistribution.DomainConsoleBackup_fixture");Directory.CreateDirectory(backup);File.WriteAllText(Path.Combine(backup,"keep.txt"),"KEEP");if(!Discover().Contains(old)||Discover().Contains(backup))throw new Exception("Orphan discovery / backup isolation failed");if(Delete(old)!=0||Exists(old)||Delete(old)!=0||!File.Exists(Path.Combine(backup,"keep.txt")))throw new Exception("Long-path / absent directory cleanup failed");Directory.CreateDirectory(old);var outside=Path.Combine(root,"outside");Directory.CreateDirectory(outside);File.WriteAllText(Path.Combine(outside,"sentinel.txt"),"KEEP");using(var process=Process.Start(new ProcessStartInfo("cmd.exe","/c mklink /J \""+Path.Combine(old,"link")+"\" \""+outside+"\""){UseShellExecute=false,CreateNoWindow=true})){process.WaitForExit();if(process.ExitCode!=0)throw new Exception("Junction fixture failed");}if(Delete(old)==0||!File.Exists(Path.Combine(outside,"sentinel.txt")))throw new Exception("Link guard failed");Directory.Delete(Path.Combine(old,"link"));Directory.Delete(old);Console.WriteLine("Long paths, idempotent removal, orphan discovery, backup preservation and junction rejection passed.");return 0;}
  public static int Run(string root){Directory.CreateDirectory(root);using(var mutex=new Mutex(false,@"Global\DomainConsoleCSharp.CacheCleanup34")){bool held=false;try{try{held=mutex.WaitOne(0);}catch(AbandonedMutexException){held=true;}if(!held){Console.WriteLine("Очистка старого кэша уже выполняется; повторный процесс не запущен.");return 0;}var manifest=Path.Combine(root,"pending-cache-cleanup.jsonl");var json=new JavaScriptSerializer();var paths=new HashSet<string>(StringComparer.OrdinalIgnoreCase);var report=new List<string>();if(File.Exists(manifest)){foreach(var line in File.ReadAllLines(manifest).Where(l=>!string.IsNullOrWhiteSpace(l))){try{var item=json.Deserialize<Dictionary<string,string>>(line);if(!Allowed(item["Path"]))throw new IOException("Недопустимый путь в очереди очистки");paths.Add(Normal(item["Path"]));}catch(Exception ex){report.Add("Некорректная запись очереди: "+ex.Message);}}}foreach(var path in Discover())paths.Add(path);try{var drive=new DriveInfo(Path.GetPathRoot(Environment.GetFolderPath(Environment.SpecialFolder.Windows)));report.Add("Свободно на диске: "+(drive.AvailableFreeSpace/1073741824d).ToString("F1")+" ГБ" );if(drive.AvailableFreeSpace<5368709120L)report.Add("Мало свободного места: старые временные каталоги следует удалить; новый сброс сам по себе место не освобождает.");}catch(Exception space){report.Add("Свободное место не определено: "+space.Message);}int failed=0,attempted=0;var keep=new HashSet<string>(StringComparer.OrdinalIgnoreCase);Console.WriteLine("Старых временных каталогов: "+paths.Count+". Резервные копии и действующий кэш не удаляются.");foreach(var path in paths){if(!Exists(path))continue;if(attempted++>=4){keep.Add(path);report.Add(path+": оставлен до следующего прохода");continue;}Console.WriteLine("Проверка и удаление: "+path);var start=new ProcessStartInfo(typeof(CacheCleanup31).Assembly.Location,"cache-delete \""+path+"\""){UseShellExecute=false,CreateNoWindow=true};using(var p=Process.Start(start)){if(!p.WaitForExit(60000)){p.Kill();p.WaitForExit();failed++;keep.Add(path);report.Add(path+": лимит удаления 60 секунд; повтор будет выполнен отдельно");}else if(p.ExitCode!=0){failed++;keep.Add(path);report.Add(path+": не удалён; подробная причина: cache-delete-error.log");}else report.Add(path+": удалён старый кэш");}}
   // Discover again: paths isolated concurrently must not disappear from the queue.
   foreach(var path in Discover())keep.Add(path);var lines=keep.Select(path=>json.Serialize(new Dictionary<string,string>{{"Path",path},{"CreatedUtc",DateTime.UtcNow.ToString("o")}})).ToArray();var tmp=manifest+"."+Guid.NewGuid().ToString("N")+".tmp";File.WriteAllLines(tmp,lines,new System.Text.UTF8Encoding(true));if(File.Exists(manifest))File.Replace(tmp,manifest,null);else File.Move(tmp,manifest);var log=DateTime.UtcNow.ToString("o")+Environment.NewLine+string.Join(Environment.NewLine,report);File.WriteAllText(Path.Combine(root,"cache-cleanup-last.log"),log);Console.WriteLine(log);Console.WriteLine("Осталось каталогов: "+keep.Count);return failed>0?1:0;
   }catch(Exception ex){try{File.WriteAllText(Path.Combine(root,"cache-cleanup-last.log"),DateTime.UtcNow.ToString("o")+Environment.NewLine+ex);}catch{}Console.Error.WriteLine(ex);return 1;}finally{if(held)mutex.ReleaseMutex();}}}
 }
}
